steps.probe:
(() => {
  window.__fc = {
    root: (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim(),
    res: (expr) => { const d = document.createElement('div'); d.style.setProperty('color', expr); document.body.append(d); const v = getComputedStyle(d).color; d.remove(); return v; },
    bgIs: (sel, expr) => { const el = document.querySelector(sel); if (el === null) return 'no-el:' + sel; const d = document.createElement('div'); d.style.setProperty('background-color', expr); document.body.append(d); const want = getComputedStyle(d).backgroundColor; d.remove(); return getComputedStyle(el).backgroundColor === want; },
    colorIs: (sel, prop, expr) => { const el = document.querySelector(sel); if (el === null) return 'no-el:' + sel; return getComputedStyle(el)[prop] === window.__fc.res(expr); },
    beforeHas: (sel, expr) => { const el = document.querySelector(sel); if (el === null) return 'no-el:' + sel; const img = getComputedStyle(el, '::before').backgroundImage; return img.includes(window.__fc.res(expr)); },
    mixIs: (sel, expr) => { const el = document.querySelector(sel); if (el === null) return 'no-el:' + sel; const d = document.createElement('div'); d.style.setProperty('background-color', 'color-mix(in srgb, ' + expr + ' 18%, transparent)'); document.body.append(d); const want = getComputedStyle(d).backgroundColor; d.remove(); return getComputedStyle(el).backgroundColor === want; },
    openLayerMenu: () => { const b = [...document.querySelectorAll('.toolbar .tb-label')].find((x) => { const t = (x.textContent || '').trim(); return t === 'Основа' || t === 'Слой 136575c9'; }); if (b === undefined) return 'no-button'; b.closest('button').click(); return 'ok'; },
    pickLayer: (title) => { const item = [...document.querySelectorAll('.menu .menu-item')].find((e) => { const l = e.querySelector('.menu-item-label'); return ((l ? l.textContent : e.textContent) || '').trim() === title; }); if (item === undefined) return 'no-item'; item.click(); return 'ok'; },
    openMenu: (title) => { const btn = document.querySelector('button[title="' + title + '"]'); if (btn === null) return 'no-btn'; btn.click(); return 'ok'; },
    pickMenuItem: (text) => { const item = [...document.querySelectorAll('.menu .menu-item')].find((b) => (b.textContent || '').includes(text)); if (item === undefined) return 'no-item'; item.click(); return 'ok'; },
    clickTreeRow: () => { const row = document.querySelector('.dialog-backdrop [role="treeitem"]'); if (row === null) return 'no-row'; row.click(); return 'ok'; },
    hasCurrentRow: () => document.querySelector('.ui-tree-row--current') !== null,
  };
  return 'ok';
})()
